def ranked_category(text: str, default: str, fallback_confidence: float) -> tuple[str, float]:
    low = text.casefold()
    best_slug = default
    best_rank = (-1, -len(low))
    for slug, keywords in CATEGORY_KEYWORDS:
        for keyword in keywords:
            end_boundary = r"(?!\w)" if keyword.isascii() and keyword.isalnum() and len(keyword) <= 5 else ""
            match = re.search(r"(?<!\w)" + re.escape(keyword) + end_boundary, low)
            if not match:
                continue
            position = match.start()
            score = (6 if position < 180 else 2) + min(4, len(keyword) // 8)
            rank = (score, -position)
            if rank > best_rank:
                best_slug = slug
                best_rank = rank
    return (best_slug, 0.85) if best_rank[0] >= 0 else (default, fallback_confidence)
